template SquareRootTemplate() {
   signal input x;
   signal input y;

   y * y === x;

   component lessThan = LessThan(252);
   lessThan.in[0] <== y;
   lessThan.in[1] <== 10944121432399673150034386095624770886016148064353456036486307527127454957569;
   lessThan.out === 1;
}

